% 2. 整合数据
data = [case1; case2; case3; case4; case5; case6];

% 3. 创建热图
figure('Color', [1 1 1]); % 白色背景
% figure
% type='tight';
% tsubplot(1,1,1,type)
% 设置 CellLabelFormat 为 ' ' 可以隐藏格子里拥挤的数字，若需显示可改为 '%.2f'
h = heatmap(data, 'CellLabelFormat', '%.2f'); 

% --- 改进 1: 扩展横坐标范围至 1-123 ---
h.XDisplayLabels = string(1:123);

% 1. 生成原始的 1 到 123 的字符串数组
% labels = string(1:123);
% % 2. 逻辑处理：除了能被 10 整除的数和最后一个数 (123) 以外，全部设为空
% % 创建一个索引：保留 10, 20, ..., 120 以及 123
% keep_idx = (mod(1:123, 10) == 0) | ((1:123) == 123);
% % 3. 将不需要显示的标签变为空字符串
% labels(~keep_idx) = "";
% % 4. 赋值给对象
% h.XDisplayLabels = labels;

h.YDisplayLabels = {'no ess', 'PSO', 'GWO', 'BPSO-PSO', 'BPSO-GWO','BPSO-EGWO'};

% --- 改进 2: 将标题移动至最右侧 ---
h.Title = 'Fault Recovery Rate'; 

% 其他轴标签设置
h.XLabel = 'Node';
% h.YLabel = 'Algorithm Cases';

%% 新增-换种思路，先不设置坐标轴，让生成的热图x轴左端下面标1，右端下面标1
% 创建 123 个空字符串
customXLabels = strings(1, 123); 
% 仅在第 1 个位置和第 123 个位置填入文字
customXLabels(1) = "1";
customXLabels(123) = "123";
h.XDisplayLabels = customXLabels;

% 4. 样式美化
colormap(sky); 
h.GridVisible = 'on'; 
h.FontName = 'Arial';
h.FontSize = 10;

% --- 改进 3: 修改纵横比 ---
% 设置窗口位置和大小：[左, 下, 宽度, 高度]
% set(gcf, 'Units', 'pixels', 'Position', [10, 10, 4000, 200]);
set(gcf, 'Units', 'pixels', 'Position', [50, 200, 1400, 250]);